import React, { useState } from "react";
import Navbar from "./Navbar";
import Footer from "./Footer";
import { Link } from 'react-router-dom';

function DashboardSales() {
  const [users] = useState([
    {
      id: 1,
      name: "Alice Johnson",
      email: "alice@example.com",
      book: "Why Him?",
      moneySpent: 120,
    },
    {
      id: 2,
      name: "Mark Smith",
      email: "mark@example.com",
      book: "Blended",
      moneySpent: 75,
    },
    {
      id: 3,
      name: "Sarah Lee",
      email: "sarah@example.com",
      book: "All the Girls that Fucked Me Over with THAT GUY",
      moneySpent: 200,
    },
  ]);

  return (
    <>
    <div className="KO">
    
          {/* Navigation (Top) */}
            <div className="Mother flex min-h-screen">
              <Link to="/Dashboard" className="text-white hover:text-indigo-600 font-lg">
                Overview
              </Link>
              <Link to="/DashboardBooks" className="text-white font-lg">
                Books
              </Link>
              <Link to="/DashboardSales" className="text-white hover:text-indigo-600 font-lg">
                Sales
              </Link>
            </div>

      <div className="bg-white p-6 rounded-2xl shadow-md">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-gray-100">
              <th className="p-3">Name</th>
              <th className="p-3">Email</th>
              <th className="p-3">Book</th>
              <th className="p-3">Money Spent</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user.id} className="border-t">
                <td className="p-3 font-medium">{user.name}</td>
                <td className="p-3 text-gray-600">{user.email}</td>
                <td className="p-3 text-gray-600">{user.book}</td>
                <td className="p-3 font-semibold text-indigo-600">
                  ${user.moneySpent}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
    </>
  );
}

export default DashboardSales;
